from hypothesis import strategies as st
from math import isqrt

@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    if draw(st.booleans()):
        # Build S from a random square (zero-padded to n digits), then shuffle,
        # so that the answer is usually non-zero.
        k = draw(st.integers(0, isqrt(10 ** n - 1)))
        digits = list(str(k * k).zfill(n))
        perm = draw(st.permutations(digits))
        s = "".join(perm)
    else:
        s = "".join(draw(st.lists(st.sampled_from("0123456789"), min_size=n, max_size=n)))
    return f"{n}\n{s}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    if not t[0].isdigit():
        return False
    n = int(t[0])
    s = t[1]
    if not (1 <= n <= 13):
        return False
    if len(s) != n:
        return False
    return all(c in "0123456789" for c in s)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    s = t[1]
    target = sorted(s)
    limit = 10 ** n
    count = 0
    for k in range(isqrt(limit - 1) + 1):
        sq = k * k
        if sq >= limit:
            break
        if sorted(str(sq).zfill(n)) == target:
            count += 1
    return str(count)
