@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # all equal digits
        d = draw(st.integers(0, 9))
        s = str(d) * n
    elif mode == 1:
        # zeros and ones, many duplicates and leading zeros
        s = ''.join(draw(st.lists(st.sampled_from('01'), min_size=n, max_size=n)))
    else:
        s = ''.join(draw(st.lists(st.sampled_from('0123456789'), min_size=n, max_size=n)))
